package com.ghosthunterpro;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.hardware.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.text.SimpleDateFormat;
import java.util.*;

/** Local-first environmental recorder. Measurements are never classified as paranormal. */
public class MainActivity extends Activity implements SensorEventListener {
    private static final int BG=Color.rgb(9,15,16), CARD=Color.rgb(20,29,30), LINE=Color.rgb(39,51,51), MINT=Color.rgb(149,224,191), TEXT=Color.rgb(237,242,238), SUB=Color.rgb(145,161,157), AMBER=Color.rgb(225,184,112), RED=Color.rgb(226,124,112);
    private SensorManager sensors; private final List<Sensor> available=new ArrayList<>(); private final List<String> rows=new ArrayList<>(); private final List<float[]> magneticHistory=new ArrayList<>();
    private LinearLayout page, sensorCards; private TextView timeLabel,statusLabel,sampleLabel,inventoryLabel; private Button startButton, stopButton; private boolean recording=false,paused=false; private long started; private int sampleCount=0; private String sessionId="";
    private float mx,my,mz,ax,ay,az,gx,gy,gz,lux=Float.NaN,pressure=Float.NaN; private final Handler handler=new Handler();
    private final Runnable clock=new Runnable(){@Override public void run(){if(recording){updateClock();refreshReadings();handler.postDelayed(this,1000);}}};
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);sensors=(SensorManager)getSystemService(SENSOR_SERVICE);setup(); discover();}
    private void setup(){
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);page=new LinearLayout(this);page.setOrientation(1);page.setPadding(d(22),d(22),d(22),d(30));page.setBackgroundColor(BG);scroll.addView(page);setContentView(scroll);
        TextView brand=label("FIELDWORK     /     GHOST HUNTER PRO",11,MINT);brand.setLetterSpacing(.12f);put(brand,0,0,0,20);
        LinearLayout titleRow=new LinearLayout(this);titleRow.setGravity(Gravity.CENTER_VERTICAL);page.addView(titleRow,lp(-1,-2,0,0,0,4));LinearLayout titles=new LinearLayout(this);titles.setOrientation(1);titleRow.addView(titles,new LinearLayout.LayoutParams(0,-2,1));TextView title=label("Investigation",29,TEXT);title.setTypeface(null,1);titles.addView(title);titles.addView(label("Evidence-led field recorder",14,SUB));
        TextView badge=label("LOCAL\nONLY",10,MINT);badge.setGravity(Gravity.CENTER);badge.setPadding(d(12),d(8),d(12),d(8));badge.setBackground(round(CARD,12));titleRow.addView(badge);
        LinearLayout hero=card();hero.setOrientation(1);page.addView(hero,lp(-1,-2,0,24,0,14));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);hero.addView(top);TextView session=label("LIVE SESSION",11,SUB);session.setLetterSpacing(.1f);top.addView(session,new LinearLayout.LayoutParams(0,-2,1));View led=new View(this);led.setBackground(round(MINT,99));top.addView(led,lp(8,8,0,0,0,0));
        timeLabel=label("00:00:00",38,TEXT);timeLabel.setTypeface(null,1);timeLabel.setFontFeatureSettings("tnum");hero.addView(timeLabel,lp(-1,-2,0,6,0,0));statusLabel=label("Ready when you are",13,SUB);hero.addView(statusLabel,lp(-1,-2,0,2,0,0));
        LinearLayout metrics=new LinearLayout(this);metrics.setPadding(0,d(16),0,0);hero.addView(metrics);metric(metrics,"SAMPLES","0");metric(metrics,"SENSORS","0");metric(metrics,"MODE","IDLE");
        startButton=actionButton("START INVESTIGATION",MINT,BG);hero.addView(startButton,lp(-1,54,0,16,0,0));startButton.setOnClickListener(v->toggle()); stopButton=actionButton("FINISH & SAVE SESSION",CARD,AMBER); stopButton.setVisibility(View.GONE); hero.addView(stopButton,lp(-1,48,0,8,0,0)); stopButton.setOnClickListener(v->endSession());
        LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);page.addView(head,lp(-1,-2,0,16,0,10));TextView sh=label("INSTRUMENTS",12,SUB);sh.setTypeface(null,1);head.addView(sh,new LinearLayout.LayoutParams(0,-2,1));TextView live=label("LIVE READINGS",10,MINT);head.addView(live);
        inventoryLabel=label("",12,SUB);page.addView(inventoryLabel,lp(-1,-2,0,0,0,8));sensorCards=new LinearLayout(this);sensorCards.setOrientation(1);page.addView(sensorCards);
        LinearLayout tools=new LinearLayout(this);tools.setGravity(Gravity.CENTER_VERTICAL);page.addView(tools,lp(-1,-2,0,18,0,8));TextView toolsTitle=label("FIELD LOG",12,SUB);toolsTitle.setTypeface(null,1);tools.addView(toolsTitle,new LinearLayout.LayoutParams(0,-2,1));
        Button mark=actionButton("＋  ADD OBSERVATION",CARD,TEXT);page.addView(mark,lp(-1,50,0,0,0,9));mark.setOnClickListener(v->addObservation());
        Button library=actionButton("OPEN SAVED SESSIONS",CARD,TEXT);page.addView(library,lp(-1,50,0,0,0,9));library.setOnClickListener(v->openLibrary());
        Button export=actionButton("EXPORT RAW DATA CSV",CARD,MINT);page.addView(export,lp(-1,50,0,0,0,0));export.setOnClickListener(v->export());
        LinearLayout notice=card();notice.setOrientation(1);page.addView(notice,lp(-1,-2,0,20,0,0));TextView nt=label("IMPORTANT CONTEXT",11,AMBER);nt.setTypeface(null,1);notice.addView(nt);notice.addView(label("This app measures environmental signals; it does not detect or communicate with entities. Readings can be affected by device hardware, movement, metal, electronics, and the environment. Not safety equipment.",12,SUB),lp(-1,-2,0,7,0,0));
    }
    private void discover(){int[] types={Sensor.TYPE_MAGNETIC_FIELD,Sensor.TYPE_ACCELEROMETER,Sensor.TYPE_GYROSCOPE,Sensor.TYPE_LIGHT,Sensor.TYPE_PRESSURE};String[] names={"Magnetometer","Accelerometer","Gyroscope","Ambient light","Barometer"};StringBuilder summary=new StringBuilder();for(int i=0;i<types.length;i++){Sensor s=sensors.getDefaultSensor(types[i]);if(s!=null)available.add(s);summary.append(s==null?"○ ":"● ").append(names[i]).append(s==null?" unavailable":" ready").append("   ");}inventoryLabel.setText(summary.toString());refreshReadings();}
    private void toggle(){if(!recording){begin();}else if(paused){paused=false;for(Sensor s:available)sensors.registerListener(this,s,SensorManager.SENSOR_DELAY_NORMAL);statusLabel.setText("Recording · keep app in foreground");startButton.setText("PAUSE SESSION");}else{paused=true;sensors.unregisterListener(this);statusLabel.setText("Paused · tap resume to continue");startButton.setText("RESUME SESSION");return;}if(!recording)return;}
    private void begin(){recording=true;paused=false;started=SystemClock.elapsedRealtime();sampleCount=0;sessionId=new SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date());rows.clear();rows.add("elapsed_realtime_ns,wall_time,sensor,x,y,z,accuracy");statusLabel.setText("Recording · keep app in foreground");startButton.setText("PAUSE SESSION");stopButton.setVisibility(View.VISIBLE);startButton.setBackgroundTintList(android.content.res.ColorStateList.valueOf(AMBER));for(Sensor s:available)sensors.registerListener(this,s,SensorManager.SENSOR_DELAY_NORMAL);handler.post(clock);}
    private void endSession(){recording=false;paused=false;sensors.unregisterListener(this);handler.removeCallbacks(clock);startButton.setText("START NEW SESSION");stopButton.setVisibility(View.GONE);startButton.setBackgroundTintList(android.content.res.ColorStateList.valueOf(MINT));saveSession();statusLabel.setText("Session saved on this device · "+sampleCount+" samples");}
    private void saveSession(){try{File dir=new File(getFilesDir(),"sessions");if(!dir.exists())dir.mkdirs();File f=new File(dir,"session-"+sessionId+".csv");try(Writer w=new OutputStreamWriter(new FileOutputStream(f),StandardCharsets.UTF_8)){for(String row:rows)w.write(row+"\n");}}catch(IOException e){statusLabel.setText("Could not save session: "+e.getMessage());}}
    @Override public void onSensorChanged(SensorEvent e){if(!recording||paused)return;float[] v=e.values;int type=e.sensor.getType();if(type==Sensor.TYPE_MAGNETIC_FIELD){mx=v[0];my=v[1];mz=v[2];}else if(type==Sensor.TYPE_ACCELEROMETER){ax=v[0];ay=v[1];az=v[2];}else if(type==Sensor.TYPE_GYROSCOPE){gx=v[0];gy=v[1];gz=v[2];}else if(type==Sensor.TYPE_LIGHT)lux=v[0];else if(type==Sensor.TYPE_PRESSURE)pressure=v[0];String wall=new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSSZ",Locale.US).format(new Date());rows.add(e.timestamp+","+wall+","+e.sensor.getName().replace(',',' ')+","+v[0]+","+(v.length>1?v[1]:"")+","+(v.length>2?v[2]:"")+","+e.accuracy);sampleCount++;}
    @Override public void onAccuracyChanged(Sensor s,int accuracy){}
    private void refreshReadings(){if(sensorCards==null)return;sensorCards.removeAllViews();readingCard("MAGNETIC FIELD",String.format(Locale.US,"X  %+.2f     Y  %+.2f     Z  %+.2f µT",mx,my,mz),"Nearby metal and powered electronics can affect readings.");readingCard("MOTION CONTEXT",String.format(Locale.US,"Accel  %+.2f  %+.2f  %+.2f m/s²",ax,ay,az),"Movement context · not an anomaly indicator.");readingCard("ROTATION",String.format(Locale.US,"Gyro  %+.2f  %+.2f  %+.2f rad/s",gx,gy,gz),"Device orientation and handling context.");readingCard("AMBIENT SENSORS",(Float.isNaN(lux)?"Light unavailable":String.format(Locale.US,"Light %.1f lx",lux))+"     ·     "+(Float.isNaN(pressure)?"Pressure unavailable":String.format(Locale.US,"%.1f hPa",pressure)),"Phone temperature is not a room-temperature reading.");sampleLabel.setText(String.valueOf(sampleCount));}
    private void readingCard(String heading,String val,String note){LinearLayout c=card();c.setOrientation(1);sensorCards.addView(c,lp(-1,-2,0,0,0,8));LinearLayout r=new LinearLayout(this);c.addView(r);TextView h=label(heading,10,SUB);h.setLetterSpacing(.08f);r.addView(h,new LinearLayout.LayoutParams(0,-2,1));View dot=new View(this);dot.setBackground(round(MINT,99));r.addView(dot,lp(6,6,0,2,0,0));TextView v=label(val,15,TEXT);v.setTypeface(null,1);c.addView(v,lp(-1,-2,0,8,0,3));c.addView(label(note,11,SUB));}
    private void addObservation(){EditText input=new EditText(this);input.setHint("What did you observe? Include context or possible explanations.");input.setTextColor(TEXT);input.setHintTextColor(SUB);new AlertDialog.Builder(this).setTitle("Timestamped observation").setView(input).setNegativeButton("CANCEL",null).setPositiveButton("ADD",(d,w)->{String note=input.getText().toString().trim();if(note.isEmpty())return;String ts=new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSSZ",Locale.US).format(new Date());String entry="# OBSERVATION "+ts+",elapsed_ms="+(recording?SystemClock.elapsedRealtime()-started:0)+",\""+note.replace("\"","\"\"")+"\"";rows.add(entry);if(!recording&& !sessionId.isEmpty())saveSession();Toast.makeText(this,"Observation timestamped",Toast.LENGTH_SHORT).show();}).show();}
    private void openLibrary(){File dir=new File(getFilesDir(),"sessions");File[] files=dir.listFiles((d,n)->n.endsWith(".csv"));if(files==null||files.length==0){new AlertDialog.Builder(this).setTitle("Saved sessions").setMessage("No completed sessions on this device yet.").setPositiveButton("OK",null).show();return;}String[] names=new String[files.length];for(int i=0;i<files.length;i++)names[i]=files[i].getName().replace("session-","").replace(".csv","");new AlertDialog.Builder(this).setTitle("Saved sessions · this device").setItems(names,(dialog,which)->{try{rows.clear();try(BufferedReader reader=new BufferedReader(new InputStreamReader(new FileInputStream(files[which]),StandardCharsets.UTF_8))){String line;while((line=reader.readLine())!=null)rows.add(line);}sessionId=names[which];statusLabel.setText("Loaded saved session · "+rows.size()+" records");Toast.makeText(this,"Session loaded for export",Toast.LENGTH_SHORT).show();}catch(IOException e){Toast.makeText(this,"Could not open session",Toast.LENGTH_LONG).show();}}).setNegativeButton("CANCEL",null).show();}
    private void export(){if(rows.size()<=1){Toast.makeText(this,"Start a session and capture readings first.",Toast.LENGTH_SHORT).show();return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,"ghost-hunter-"+(sessionId.isEmpty()?"session":sessionId)+".csv");startActivityForResult(i,42);}
    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==42&&result==RESULT_OK&&data!=null)try(OutputStream out=getContentResolver().openOutputStream(data.getData())){for(String row:rows)out.write((row+"\n").getBytes(StandardCharsets.UTF_8));Toast.makeText(this,"CSV exported",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Export failed",Toast.LENGTH_LONG).show();}}
    private void updateClock(){long seconds=(SystemClock.elapsedRealtime()-started)/1000;timeLabel.setText(String.format(Locale.US,"%02d:%02d:%02d",seconds/3600,(seconds/60)%60,seconds%60));}
    private void metric(LinearLayout parent,String name,String initial){LinearLayout col=new LinearLayout(this);col.setOrientation(1);parent.addView(col,new LinearLayout.LayoutParams(0,-2,1));col.addView(label(name,9,SUB));TextView val=label(initial,13,TEXT);val.setTypeface(null,1);col.addView(val);if(name.equals("SAMPLES"))sampleLabel=val;if(name.equals("SENSORS"))val.setText(String.valueOf(available.size()));}
    private LinearLayout card(){LinearLayout l=new LinearLayout(this);l.setPadding(d(16),d(14),d(16),d(14));l.setBackground(round(CARD,16));return l;}
    private Button actionButton(String text,int color,int fg){Button b=new Button(this);b.setText(text);b.setTextColor(fg);b.setTextSize(12);b.setTypeface(null,1);b.setLetterSpacing(.07f);b.setBackground(round(color,14));b.setAllCaps(false);return b;}
    private TextView label(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
    private void put(View v,int l,int t,int r,int b){page.addView(v,lp(-1,-2,l,t,r,b));}private int d(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}private LinearLayout.LayoutParams lp(int w,int h,int l,int t,int r,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w<0?w:d(w),h<0?h:d(h));p.setMargins(d(l),d(t),d(r),d(b));return p;}
    private android.graphics.drawable.GradientDrawable round(int color,int radius){android.graphics.drawable.GradientDrawable g=new android.graphics.drawable.GradientDrawable();g.setColor(color);g.setCornerRadius(d(radius));if(color==CARD)g.setStroke(d(1),LINE);return g;}
    @Override protected void onDestroy(){if(recording)endSession();sensors.unregisterListener(this);handler.removeCallbacks(clock);super.onDestroy();}
}
